/**
 * i18n система для seismo.ru (СРОСС®) — RU/EN/ZH (ЗАКОН №3, эталон iznaki→aipat/mktu/iqin)
 *
 * Логика:
 * - Cookie `lang` хранит выбор пользователя ('ru' | 'en' | 'zh')
 * - URL /en/... или /zh/... middleware rewrite → тот же компонент, но lang=xx
 * - useLanguage() hook читает язык и возвращает t() функцию
 *
 * ЭТАП 2 (доливка, прецедент «ВРЕМЕННО RU»): содержимое iframe-виджетов
 * (/public/earthquake-map.html, /public/earthquake-simulator.html), заголовки
 * новостей (news-headlines.json) и справка событий
 * (spravka-zemletryaseniya.json) остаются RU.
 */

export type Lang = 'ru' | 'en' | 'zh';

export const DEFAULT_LANG: Lang = 'ru';

export const LANGUAGES: { code: Lang; label: string; nativeName: string }[] = [
  { code: 'ru', label: 'RU', nativeName: 'Русский' },
  { code: 'en', label: 'EN', nativeName: 'English' },
  { code: 'zh', label: '中', nativeName: '中文' },
];

