  'dir.15t': { ru: 'СейсмоУсиление', en: 'Seismic strengthening', zh: '抗震加固' },
  'dir.15x': { ru: 'Технологии сейсмического усиления существующих конструкций', en: 'Technologies for seismic strengthening of existing structures', zh: '既有结构的抗震加固技术' },
  'dir.16t': { ru: 'Инновации', en: 'Innovation', zh: '创新' },
  'dir.16x': { ru: 'Новые строительные технологии. Внедрение инновационных материалов и технологий сейсмозащиты', en: 'New construction technologies. Introduction of innovative materials and seismic protection technologies', zh: '新建筑技术。创新材料和地震防护技术的应用' },
  'dir.17t': { ru: 'Экспертиза', en: 'Expert review', zh: '鉴定' },
  'dir.17x': { ru: 'Независимая оценка и экспертиза. Аналитическая и экспертная работа в области сейсмобезопасности', en: 'Independent assessment and expertise. Analytical and expert work in the field of seismic safety', zh: '独立评估与鉴定。地震安全领域的分析与专家工作' },
  'dir.18t': { ru: 'Защита от экстремальных воздействий', en: 'Protection from extreme impacts', zh: '极端作用防护' },
  'dir.18x': { ru: 'Антидроновая защита, защита от взрывных волн от взрывов большой мощности специализированных предприятий. Активная и пассивная защита зданий и сооружений', en: 'Anti-drone protection, protection from blast waves of high-power explosions of specialized facilities. Active and passive protection of buildings and structures', zh: '反无人机防护、专业企业大功率爆炸冲击波防护。建筑与结构的主动和被动防护' },
  'dir.19t': { ru: 'Вибросейсм', en: 'Vibroseismic', zh: '振动地震' },
  'dir.19x': { ru: 'Защита от землетрясений и вибраций. Комплексные решения по защите сооружений от сейсмических и вибрационных воздействий', en: 'Protection from earthquakes and vibrations. Integrated solutions for protecting structures from seismic and vibration impacts', zh: '地震与振动防护。结构免受地震和振动作用的综合解决方案' },
  'dir.20t': { ru: 'ИНЖГЕОТЕХ', en: 'ENGGEOTECH', zh: '工程岩土' },
  'dir.20x': { ru: 'Изыскания и исследования природы. Инженерно-геотехнические работы для строительства в сейсмических зонах', en: 'Surveys and environmental research. Engineering and geotechnical works for construction in seismic zones', zh: '勘察与自然环境研究。地震区建设的工程地质技术工作' },
  'dir.21t': { ru: 'НИР, НИОКР', en: 'R&D', zh: '科研与试验设计' },
  'dir.21x': { ru: 'Научные исследования и разработки. Фундаментальные и прикладные исследования в области сейсмобезопасности', en: 'Scientific research and development. Fundamental and applied research in the field of seismic safety', zh: '科学研究与开发。地震安全领域的基础与应用研究' },
  'dir.22t': { ru: 'TIM, Цифра', en: 'TIM, Digital', zh: 'TIM, 数字化' },
  'dir.22x': { ru: 'Цифровые технологии и развитие. Искусственный интеллект (ИИ-AI) в сейсмопрогнозах, расчётах конструкций, мониторинге и предупреждениях', en: 'Digital technologies and development. Artificial intelligence (AI) in earthquake forecasting, structural analysis, monitoring and early warning', zh: '数字技术与发展。人工智能（AI）在地震预测、结构计算、监测和预警中的应用' },
  'dir.23t': { ru: 'Депонирование', en: 'Deposit of works', zh: '成果寄存' },
  'dir.23x': { ru: 'Депонирование научных статей, авторских трудов, ноу-хау', en: 'Deposit of scientific articles, author’s works, know-how', zh: '科学论文、著作权作品、专有技术的寄存' },
  'dir.24t': { ru: 'Патентование', en: 'Patenting', zh: '专利申请' },
