  // ===== Технология «червяк» =====
  'worm.eyebrow': { ru: 'Патентованная технология', en: 'Patented technology', zh: '专利技术' },
  'worm.h3': { ru: 'ТЗ «червяк»', en: 'TS “Worm”', zh: '技术任务书“蠕虫”' },
  'worm.badge': { ru: 'Патент · Зарегистрировано в Роспатенте', en: 'Patent · Registered with Rospatent', zh: '专利 · 已在俄罗斯专利局注册' },
  'worm.p1': { ru: 'Техническое задание «червяк» — оригинальная методология сейсмологического мониторинга, разработанная авторским коллективом системы СРОСС®. Технология обеспечивает высокоточную локализацию эпицентров и оценку магнитуды сейсмических событий в реальном времени на территориях России и сопредельных регионов.', en: 'The “Worm” technical specification is an original seismic monitoring methodology developed by the SROSS® system’s author team. The technology provides high-precision epicenter localization and real-time magnitude estimation of seismic events in Russia and adjacent regions.', zh: '“蠕虫”技术任务书是由СРОСС®系统作者团队开发的原创地震监测方法。该技术可对俄罗斯及邻近地区的地震事件进行高精度震中定位和实时震级评估。' },
  'worm.p2': { ru: 'Патент защищает ключевые алгоритмические и архитектурные решения, лежащие в основе информационной системы. Использование технологии в коммерческих и государственных проектах осуществляется по лицензии через Евразийскую СЕЙСМО Ассоциацию.', en: 'The patent protects the key algorithmic and architectural solutions underlying the information system. Use of the technology in commercial and government projects is carried out under license through the Eurasian SEISMO Association.', zh: '该专利保护作为信息系统基础的关键算法和架构解决方案。在商业和政府项目中使用该技术需通过欧亚地震协会获得许可。' },

  // ===== Партнёры =====
  'part.eyebrow': { ru: '04 · Партнёры', en: '04 · Partners', zh: '04 · 合作伙伴' },
  'part.h2': { ru: 'Экосистема СРОСС®', en: 'The SROSS® ecosystem', zh: 'СРОСС® 生态系统' },
  'part.lead': { ru: 'Информационная система развивается в тесной координации с профессиональными ассоциациями, региональными представительствами и отраслевыми платформами. В экосистему входит более 9 региональных представительств ЕАЭС и стран СНГ.', en: 'The information system develops in close coordination with professional associations, regional offices and industry platforms. The ecosystem includes more than 9 regional offices across the EAEU and CIS countries.', zh: '该信息系统与专业协会、区域办事处和行业平台密切协调发展。生态系统包括欧亚经济联盟和独联体国家的9个以上区域办事处。' },
  'part.1full': { ru: 'Евразийская СЕЙСМО Ассоциация', en: 'Eurasian SEISMO Association', zh: '欧亚地震协会' },
  'part.1desc': { ru: 'Международная организация с историей более 50 лет. Координатор консорциума ГРАДОРЕСУРС® и базовых проектов системы СРОСС®.', en: 'An international organization with more than 50 years of history. Coordinator of the GRADORESOURS® consortium and the flagship projects of the SROSS® system.', zh: '拥有50多年历史的国际组织。GRAДОРЕСУРС®联盟及СРОСС®系统旗舰项目的协调者。' },
  'part.1badge': { ru: 'seismo.pro', en: 'seismo.pro', zh: 'seismo.pro' },
  'part.2full': { ru: 'Международный консорциум', en: 'International consortium', zh: '国际联盟' },
  'part.2desc': { ru: 'Координационная структура, объединяющая профессиональные организации в сфере градостроительной безопасности территорий ЕАЭС.', en: 'A coordinating body uniting professional organizations in the field of urban development safety of the EAEU territories.', zh: '联合欧亚经济联盟地区城市安全领域专业组织的协调机构。' },
  'part.2badge': { ru: 'Консорциум', en: 'Consortium', zh: '联盟' },
  'part.3full': { ru: 'Форум и выставка', en: 'Forum and exhibition', zh: '论坛与展览' },
  'part.3desc': { ru: 'Крупнейшая отраслевая площадка, посвящённая строительству и сейсмобезопасности в сейсмических регионах России.', en: 'The largest industry venue dedicated to construction and seismic safety in the seismic regions of Russia.', zh: '俄罗斯地震地区建筑与地震安全领域最大的行业平台。' },
  'part.3badge': { ru: 'Форум', en: 'Forum', zh: '论坛' },
  'part.4full': { ru: 'Международная ассоциация', en: 'International association', zh: '国际协会' },
  'part.4desc': { ru: 'Ассоциация строительных организаций стран СНГ. Площадка профессионального сотрудничества и обмена опытом.', en: 'An association of construction organizations of the CIS countries. A platform for professional cooperation and exchange of experience.', zh: '独联体国家建筑组织协会。专业合作与经验交流平台。' },
  'part.4badge': { ru: 'Ассоциация', en: 'Association', zh: '协会' },
  'part.5full': { ru: 'Российский национальный комитет', en: 'Russian National Committee', zh: '俄罗斯国家委员会' },
  'part.5desc': { ru: 'Российский национальный комитет по сейсмостойкому строительству. Представительство России в IAEE.', en: 'The Russian National Committee for Seismic-Resistant Construction. Russia’s representation in the IAEE.', zh: '俄罗斯抗震建筑国家委员会。俄罗斯在国际地震工程协会（IAEE）中的代表。' },
  'part.5badge': { ru: 'Комитет', en: 'Committee', zh: '委员会' },
