  'part.6desc': { ru: 'Профильная платформа по геотехнике и инженерным изысканиям в сейсмических зонах.', en: 'A specialized platform on geotechnics and engineering surveys in seismic zones.', zh: '地震区岩土工程和工程勘察专业平台。' },
  'part.6badge': { ru: 'Платформа', en: 'Platform', zh: '平台' },
