  'part.8desc': { ru: 'Платформа методологии оценки и управления природными и техногенными рисками территорий.', en: 'A platform for the methodology of assessing and managing natural and man-made risks of territories.', zh: '区域自然和人为风险评估与管理方法论平台。' },
  'part.8badge': { ru: 'Методология', en: 'Methodology', zh: '方法论' },
  'part.regionsEyebrow': { ru: 'Региональные представительства', en: 'Regional offices', zh: '区域办事处' },
  'part.regionsH3': { ru: '9 регионов ЕАЭС', en: '9 EAEU regions', zh: '9个欧亚经济联盟地区' },
  'part.regionsLead': { ru: 'Региональные представительства ЕАСА обеспечивают координацию экспертов на местах и работу с региональными органами власти. Открыты для присоединения новых регионов.', en: 'EASA regional offices ensure coordination of local experts and cooperation with regional authorities. Open to new regions joining.', zh: 'EASA区域办事处确保当地专家的协调以及与地区政府机关的合作。欢迎新地区加入。' },
  'part.regionsLink': { ru: 'Все представительства на seismo.pro', en: 'All offices on seismo.pro', zh: 'seismo.pro 上的全部办事处' },
  'part.r1': { ru: 'Россия / Москва', en: 'Russia / Moscow', zh: '俄罗斯 / 莫斯科' },
