  'auth.pr1c': { ru: 'Сейсмостойкое строительство', en: 'Seismic-resistant construction', zh: '抗震建筑' },
  'auth.pr1x': { ru: 'Проектирование и строительство гостиничного комплекса с применением систем сейсмоизоляции в сейсмических районах.', en: 'Design and construction of a hotel complex using seismic isolation systems in seismic areas.', zh: '在地震地区设计建造采用隔震系统的酒店综合体。' },
  'auth.pr2c': { ru: 'Градостроительное проектирование', en: 'Urban development design', zh: '城市规划设计' },
  'auth.pr2x': { ru: 'Комплексное проектирование жилого комплекса с подземной автостоянкой в сейсмической зоне, с учётом требований СП 14.13330.', en: 'Integrated design of a residential complex with an underground parking lot in a seismic zone, taking into account the requirements of SP 14.13330.', zh: '在地震区设计带地下停车场的住宅综合体，考虑СП 14.13330规范要求。' },
  'auth.pr3c': { ru: 'Промышленные объекты', en: 'Industrial facilities', zh: '工业设施' },
  'auth.pr3x': { ru: 'Установка для производства метанола производительностью 5400 метрических тонн в сутки. Проектирование сейсмостойких конструкций промышленного объекта.', en: 'A methanol production unit with a capacity of 5,400 metric tons per day. Design of seismic-resistant structures of the industrial facility.', zh: '日产5400公吨甲醇的生产装置。工业设施抗震结构设计。' },
  'auth.pr4c': { ru: 'Социальные объекты', en: 'Social facilities', zh: '社会设施' },
  'auth.pr4x': { ru: 'Проектирование и строительство медицинского центра Федерального медико-биологического агентства с обеспечением сейсмостойкости ответственных сооружений.', en: 'Design and construction of a medical center of the Federal Medical-Biological Agency with seismic resistance of critical structures ensured.', zh: '联邦医学生物署医疗中心的设计与建造，确保重要结构的抗震性。' },
